import React, { useState, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {
  faPhoneAlt,
  faEnvelope,
  faLink,
} from '@fortawesome/free-solid-svg-icons';
import CustomHook from './CustomHook';

function Contacts() {
  const divs = useRef([]);
  const scrollTab = useRef();
  divs.current = [];

  const attachRef = (el) => {
    if (el && !divs.current.includes(el)) divs.current.push(el);
  };

  // ✅ Your contact info (with icons, GitHub removed)
  const [listContacts] = useState([
    {
      title: 'Phone',
      value: '+91 9079289874',
      href: 'tel:+919079289874',
      icon: faPhoneAlt,
      aria: 'Call Punit Gupta',
    },
    {
      title: 'Email',
      value: 'punitg505@gmail.com',
      href: 'mailto:punitg505@gmail.com',
      icon: faEnvelope,
      aria: 'Email Punit Gupta',
    },
    {
      title: 'LinkedIn',
      value: 'linkedin.com/in/punit-gupta-18a930255',
      href: 'https://www.linkedin.com/in/punit-gupta-18a930255',
      icon: faLink,
      aria: 'Punit Gupta on LinkedIn',
    },
  ]);

  CustomHook(scrollTab, divs);

  return (
    <section
      className="contacts py-10 px-6 sm:px-10 bg-gray-900 text-gray-100"
      ref={scrollTab}
      aria-label="Contact Information"
    >
      <div className="title mb-6" ref={attachRef}>
        <h2 className="text-3xl font-bold tracking-tight text-white">
          Contact Me
        </h2>
        <p className="text-gray-400 mt-2">
          Feel free to reach out for collaborations, freelance work, or any
          technical discussions.
        </p>
      </div>

      <div
        className="list grid gap-6 sm:grid-cols-2 lg:grid-cols-3"
        ref={attachRef}
        role="list"
      >
        {listContacts.map((item, idx) => (
          <div
            className="item flex items-start gap-4 p-5 rounded-xl bg-gray-800 border border-gray-700 hover:border-blue-500 transition duration-300"
            key={idx}
            role="listitem"
            ref={attachRef}
          >
            <div className="icon w-10 h-10 flex items-center justify-center rounded-full bg-blue-600/10 text-blue-400 text-lg">
              <FontAwesomeIcon icon={item.icon} />
            </div>
            <div className="content">
              <h3 className="text-sm font-semibold text-gray-300">
                {item.title}
              </h3>
              <a
                href={item.href}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={item.aria}
                className="block mt-1 text-blue-400 hover:underline break-all"
              >
                {item.value}
              </a>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Contacts;
